import { GraphQLError } from 'graphql'
import { createSchema } from 'graphql-yoga'
import type { TaskStore } from './store'

export const typeDefs = /* GraphQL */ `
  type Task {
    id: ID!
    title: String!
    done: Boolean!
    createdAt: String!
  }

  enum TaskFilter {
    ALL
    OPEN
    DONE
  }

  type Query {
    tasks(filter: TaskFilter = ALL): [Task!]!
    task(id: ID!): Task
  }

  type Mutation {
    addTask(title: String!): Task!
    toggleTask(id: ID!): Task!
    deleteTask(id: ID!): Boolean!
  }
`

export const MAX_TITLE = 120

function validTitle(raw: string): string {
  const title = raw.trim()
  if (!title) throw new GraphQLError('Title is required')
  if (title.length > MAX_TITLE) {
    throw new GraphQLError(`Title must be at most ${MAX_TITLE} characters`)
  }
  return title
}

export function buildSchema(store: TaskStore) {
  return createSchema({
    typeDefs,
    resolvers: {
      Query: {
        tasks: (_: unknown, args: { filter: 'ALL' | 'OPEN' | 'DONE' }) => {
          const all = store.list()
          if (args.filter === 'OPEN') return all.filter((t) => !t.done)
          if (args.filter === 'DONE') return all.filter((t) => t.done)
          return all
        },
        task: (_: unknown, args: { id: string }) => store.get(args.id) ?? null,
      },
      Mutation: {
        addTask: (_: unknown, args: { title: string }) => store.add(validTitle(args.title)),
        toggleTask: (_: unknown, args: { id: string }) => {
          const task = store.toggle(args.id)
          if (!task) throw new GraphQLError(`No task with id ${args.id}`)
          return task
        },
        deleteTask: (_: unknown, args: { id: string }) => store.remove(args.id),
      },
    },
  })
}

