import { beforeEach, describe, expect, it } from 'vitest'
import { createApp } from './app'
import { TaskStore } from './store'

let yoga: ReturnType<typeof createApp>

async function gql(query: string, variables: Record<string, unknown> = {}) {
  const res = await yoga.fetch('http://test/graphql', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ query, variables }),
  })
  return res.json() as Promise<{ data?: any; errors?: { message: string }[] }>
}

beforeEach(() => {
  yoga = createApp(new TaskStore(['one', 'two']))
})

describe('tasks', () => {
  it('lists tasks', async () => {
    const { data } = await gql('{ tasks { id title done } }')
    expect(data.tasks.map((t: any) => t.title)).toEqual(['one', 'two'])
  })

  it('adds a task and trims the title', async () => {
    const { data } = await gql('mutation($t: String!) { addTask(title: $t) { title done } }', {
      t: '  three  ',
    })
    expect(data.addTask).toEqual({ title: 'three', done: false })
  })

  it('rejects an empty title', async () => {
    const { errors } = await gql('mutation { addTask(title: "   ") { id } }')
    expect(errors?.[0].message).toBe('Title is required')
  })

  it('toggles a task and filters by state', async () => {
    await gql('mutation { toggleTask(id: "1") { done } }')
    const open = await gql('{ tasks(filter: OPEN) { id } }')
    const done = await gql('{ tasks(filter: DONE) { id } }')
    expect(open.data.tasks).toEqual([{ id: '2' }])
    expect(done.data.tasks).toEqual([{ id: '1' }])
  })

  it('errors when toggling an unknown id', async () => {
    const { errors } = await gql('mutation { toggleTask(id: "99") { id } }')
    expect(errors?.[0].message).toBe('No task with id 99')
  })

  it('deletes a task', async () => {
    const { data } = await gql('mutation { deleteTask(id: "1") }')
    expect(data.deleteTask).toBe(true)
    const list = await gql('{ tasks { id } }')
    expect(list.data.tasks).toEqual([{ id: '2' }])
  })
})

