import { useState } from 'react'
import { useMutation, useQuery } from 'urql'
import { AddTaskForm } from './AddTaskForm'
import { ADD_TASK, DELETE_TASK, TASKS, TOGGLE_TASK, type Filter, type Task } from './graphql'
import { TaskItem } from './TaskItem'

const FILTERS: Filter[] = ['ALL', 'OPEN', 'DONE']

export function App() {
  const [filter, setFilter] = useState<Filter>('ALL')
  const [{ data, fetching, error }, refetch] = useQuery<{ tasks: Task[] }>({
    query: TASKS,
    variables: { filter },
  })
  const [, addTask] = useMutation(ADD_TASK)
  const [, toggleTask] = useMutation(TOGGLE_TASK)
  const [, deleteTask] = useMutation(DELETE_TASK)

  const reload = () => refetch({ requestPolicy: 'network-only' })
  const tasks = data?.tasks ?? []

  return (
    <main>
      <h1>Tasks</h1>
      <AddTaskForm onAdd={(title) => addTask({ title }).then(reload)} />
      <nav>
        {FILTERS.map((f) => (
          <button key={f} aria-pressed={f === filter} onClick={() => setFilter(f)}>
            {f.toLowerCase()}
          </button>
        ))}
      </nav>
      {error && <p role="alert">{error.message}</p>}
      {fetching && !data && <p>Loading…</p>}
      <ul>
        {tasks.map((task) => (
          <TaskItem
            key={task.id}
            task={task}
            onToggle={(id) => toggleTask({ id }).then(reload)}
            onDelete={(id) => deleteTask({ id }).then(reload)}
          />
        ))}
      </ul>
      {!fetching && tasks.length === 0 && <p>Nothing here yet.</p>}
    </main>
  )
}

